skins.css:
/* BLOCK - lifted straight out of block/index.html, which was never wearing a
   theme at all: it loads day.js and records.js and nothing else, and every
   colour in it is its own.

   Its structure was already right. Fifteen variables, borders doing all the
   separating, almost no shadow anywhere, six-pixel corners, and two fonts - a
   squared one for labels and a plain one for reading. That is a theme, it was
   just written inside one app where nothing else could reach it.

   Measured rather than eyeballed: 6px is the corner in 37 places, borders are
   1px #1e2a38, and exactly three elements in the whole app carry a shadow. */

body { letter-spacing: var(--track-body) }

/* Flat depth removes the shadow, so the edge has to come from a line. That is
   how BLOCK does it too: a hairline round everything and no lift at all. */
.card, .mb-sheet, .mb-menu, .mb-toast {
  background: var(--surface-1);
  border: var(--border-width) solid var(--border);
}
header {
  background: var(--surface-1);
  border-bottom: var(--border-width) solid var(--border);
}
header .logo { font-family: var(--font-display); letter-spacing: var(--track-cap) }

h2 {
  font-family: var(--font-display);
  color: var(--text-muted);
  letter-spacing: var(--track-cap);
}

.item, .mb-input, .mb-sel {
  background: var(--surface-2);
  border: var(--border-width) solid var(--border);
}
.item .nm { font-family: var(--font-body) }

.chk { border-color: var(--border-strong) }
.chk.on { background: var(--accent); border-color: var(--accent); color: var(--accent-fg) }

.stat { background: var(--surface-2); border: var(--border-width) solid var(--border) }
.stat b { font-family: var(--font-display) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display);
  letter-spacing: var(--track-cap);
  background: var(--surface-2);
  border: var(--border-width) solid var(--border);
  color: var(--text-2);
}
button.mb-btn:hover, .mb-chip:hover { border-color: var(--border-strong); color: var(--text-1) }
.mb-btn.go { border-color: var(--accent); color: var(--accent); background: var(--surface-2) }
#fab { background: var(--accent); color: var(--accent-fg) }
